<script lang="ts">
 import {displayPath} from "./storage";import type {DatabaseCatalog} from "./database-catalog";import {Database,Plus,FolderOpen,ArrowRight,X,Trash2} from "@lucide/svelte";import {translator} from "./i18n";
 export let catalog:DatabaseCatalog;export let language:"ru"|"ro";export let active="default";export let onopen:(id:string)=>Promise<void>;export let onnew:(name:string)=>Promise<void>;export let onimport:()=>Promise<void>;export let onremove:(id:string)=>Promise<void>;export let onauto:(id:string|null)=>Promise<void>;
 let name="",busy=false,creating=false; $:t=translator(language);
 async function open(id:string){busy=true;try{await onopen(id);}finally{busy=false;}}
 async function remove(id:string){busy=true;try{await onremove(id);}finally{busy=false;}}
</script>
<div class="database-home">
 <aside><img src="/brand/logo-full.svg" alt="OpenHaU OPEN"/><button class="button" disabled={busy} onclick={()=>creating=true}><Plus size={18}/>{t("Создать базу","Creează o bază")}</button><button class="button secondary" disabled={busy} onclick={onimport}><FolderOpen size={18}/>{t("Добавить существующую","Adaugă o bază existentă")}</button></aside>
 <section><h1>{t("Базы данных","Baze de date")}</h1><div class="database-cards">{#each catalog.databases as db}<article class="database-entry"><button class="database-card" disabled={busy} onclick={()=>open(db.id)}><Database size={32}/><strong>{db.name}</strong>{#if db.path}<small class="database-path" title={displayPath(db.path)}>{displayPath(db.path)}</small>{/if}{#if active===db.id}<small>{t("Текущая база","Baza curentă")}</small>{/if}<span><ArrowRight size={18}/>{t("Открыть","Deschide")}</span></button><button class="icon-button remove-database" disabled={busy} title={t("Убрать из списка · файл останется на диске","Elimină din listă · fișierul rămâne pe disc")} aria-label={t("Убрать из списка: ","Elimină din listă: ")+db.name} onclick={()=>remove(db.id)}><Trash2 size={17}/></button></article>{/each}{#if !catalog.databases.length}<p class="empty-list">{t("Добавьте существующую базу или создайте новую.","Adăugați o bază existentă sau creați una nouă.")}</p>{/if}</div><label>{t("Автоматически открывать при запуске","Deschidere automată la pornire")}<select value={catalog.auto||""} onchange={e=>onauto(e.currentTarget.value||null)}><option value="">{t("Показывать выбор базы","Afișează alegerea bazei")}</option>{#each catalog.databases as db}<option value={db.id}>{db.name}</option>{/each}</select></label></section>
</div>
{#if creating}<div class="create-backdrop" role="presentation"><div class="create-dialog" role="dialog" aria-modal="true" aria-label={t("Создать базу","Creează o bază")} tabindex="-1"><header><strong>{t("Создать базу","Creează o bază")}</strong><button class="icon-button" aria-label={t("Закрыть","Închide")} onclick={()=>creating=false}><X size={18}/></button></header><input aria-label={t("Название новой базы","Denumirea bazei noi")} bind:value={name}/><button class="button" disabled={busy||!name.trim()} onclick={async()=>{busy=true;try{await onnew(name);name="";creating=false;}finally{busy=false;}}}><Plus size={16}/>{t("Создать","Creează")}</button></div></div>{/if}
<style>.database-home{display:grid;grid-template-columns:190px minmax(0,1fr);height:100%;min-width:0;overflow:hidden}.database-home aside{display:flex;flex-direction:column;gap:16px;padding:24px 14px;background:var(--sidebar);border-right:1px solid var(--border)}aside img{width:110px;margin:0 auto 20px;opacity:.8;filter:brightness(0)}:global(:root[data-theme="dark"]) aside img{filter:none}.database-home section{padding:24px;min-width:0;overflow-x:hidden;overflow-y:auto}.database-home h1{font-size:26px;font-weight:400;margin:0 0 30px}.create-backdrop{position:fixed;inset:0;z-index:30000;display:grid;place-items:center;background:#0005}.create-dialog{width:min(380px,90vw);display:grid;gap:18px;padding:24px;background:var(--surface);border:1px solid var(--border)}.create-dialog header{display:flex;justify-content:space-between;align-items:center}.database-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(150px,100%),1fr));gap:12px;margin:18px 0}.database-entry{position:relative;min-width:0}.remove-database{position:absolute;top:5px;right:5px}.database-card{width:100%;min-width:0;box-sizing:border-box;overflow-wrap:anywhere;display:flex;flex-direction:column;gap:16px;align-items:flex-start;text-align:left;padding:38px 16px 16px;background:transparent;border:1px solid transparent;color:var(--text);min-height:130px}.database-card:hover{border-color:var(--reveal-ink,#0002);background:var(--hover)}.database-card>:global(svg),.database-card>span{color:var(--accent)}.database-card span{display:flex;gap:8px;align-items:center}.database-home label{display:flex;flex-direction:column;gap:12px;max-width:440px}.database-path{max-width:100%;overflow-wrap:anywhere}.database-home small{color:var(--muted)}.database-home select,.database-home strong{min-width:0;max-width:100%;box-sizing:border-box}.empty-list{overflow-wrap:anywhere}.database-home aside .button{white-space:normal;text-align:left}</style>


